// Generates src/lib/agentDefinitions.generated.ts from the canonical Claude
// Code subagent definitions in ../.claude/agents/*.md.
//
// Why generate instead of reading the .md files at runtime: those files live
// outside the Next.js app root, so Next's build tracing never bundles them
// and `fs.readFileSync` throws ENOENT on any real deployment (Vercel, Docker
// standalone, anything where the app is served from its own directory). The
// prompts have to be inside the compiled bundle to survive deploy.
//
// The generated file is committed so a build works even when the parent
// .claude/ directory isn't part of the deployment context. Run with --check
// (as CI does) to fail if it has drifted from the source .md files.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import matter from "gray-matter";

const here = path.dirname(fileURLToPath(import.meta.url));
const APP_DIR = path.join(here, "..");
const AGENTS_DIR = path.join(APP_DIR, "..", ".claude", "agents");
const OUT_FILE = path.join(APP_DIR, "src", "lib", "agentDefinitions.generated.ts");

// Mirrors AGENT_FILES in src/lib/agents.ts — the AgentName enum values from
// the Prisma schema mapped to their source markdown.
const AGENT_FILES = {
  MARKET_SIGNAL_RESEARCHER: "market-signal-researcher.md",
  OFFER_ARCHITECT: "offer-architect.md",
  CONTENT_ANGLE_STRATEGIST: "content-angle-strategist.md",
  CONVERSATION_SYSTEM_BUILDER: "conversation-system-builder.md",
};

function build() {
  const entries = Object.entries(AGENT_FILES).map(([agent, file]) => {
    const filePath = path.join(AGENTS_DIR, file);
    if (!fs.existsSync(filePath)) {
      throw new Error(
        `Missing agent definition: ${filePath}\n` +
          `Every name in AGENT_FILES must have a matching .md in .claude/agents/.`
      );
    }
    const { data, content } = matter(fs.readFileSync(filePath, "utf-8"));
    const systemPrompt = content.trim();
    if (!systemPrompt) throw new Error(`${file} has frontmatter but no prompt body.`);
    return { agent, sourceFile: file, description: data.description ?? "", systemPrompt };
  });

  const body = entries
    .map(
      (e) =>
        `  ${e.agent}: {\n` +
        `    sourceFile: ${JSON.stringify(e.sourceFile)},\n` +
        `    description: ${JSON.stringify(e.description)},\n` +
        `    systemPrompt: ${JSON.stringify(e.systemPrompt)},\n` +
        `  },`
    )
    .join("\n");

  return (
    `// @generated by scripts/sync-agent-definitions.mjs — DO NOT EDIT BY HAND.\n` +
    `// Source of truth: .claude/agents/*.md at the repository root.\n` +
    `// Regenerate with: npm run sync:agents\n\n` +
    `export interface GeneratedAgentDefinition {\n` +
    `  sourceFile: string;\n` +
    `  description: string;\n` +
    `  systemPrompt: string;\n` +
    `}\n\n` +
    `export const AGENT_DEFINITIONS: Record<string, GeneratedAgentDefinition> = {\n` +
    `${body}\n};\n`
  );
}

const generated = build();
const check = process.argv.includes("--check");
const current = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, "utf-8") : null;

if (check) {
  if (current !== generated) {
    console.error(
      "agentDefinitions.generated.ts is out of sync with .claude/agents/*.md.\n" +
        "Run `npm run sync:agents` and commit the result."
    );
    process.exit(1);
  }
  console.log("Agent definitions are in sync.");
} else if (current === generated) {
  console.log("Agent definitions already up to date.");
} else {
  fs.writeFileSync(OUT_FILE, generated);
  console.log(`Wrote ${path.relative(APP_DIR, OUT_FILE)}`);
}
